     "items": {
      "enum": [
       "api",
       "frontend",
       "backend",
       "infrastructure",
       "data",
       "security"
      ]
     }
    }
   }
  }
 },
 {
  "if": {
   "properties": {
    "artifact_kind": {
     "enum": [
      "issue",
      "task",
      "document",
      "feature"
     ]
    }
   }
  },
